files.loader.py:
"""把文本解析成配置字典。"""

from __future__ import annotations


def load_settings(text):
    """解析 key=value 文本；值里含 `=` 时只按第一个 `=` 切分。"""
    result = {}
    for line in text.splitlines():
        if not line.strip() or line.startswith("#"):
            continue
        key, value = line.split("=")
        result[key.strip()] = value.strip()
    return result

