files.sweeper.py:
"""清理过期项。"""

from __future__ import annotations


def sweep(store, ttl, clock):
    """删除过期条目。"""
    for key in [k for k, (t, _) in store.items() if clock() - t >= ttl]:
        del store[key]
    return len(store)

